import { cn } from "cn";
import { WormholeLandscape } from "@/components/auth/wormhole-landscape";
import { WormholePortrait } from "@/components/auth/wormhole-portrait";

/**
 * The login backdrop: the brand's Apollonian construction (generated by the `network-create`
 * skill, `scenes/flat/backdrop.mjs`), in a landscape and a transposed portrait cut. Its two limit
 * points stand either side of the form (above and below it on a phone), and
 * the pivot sits under the form's centre. A radial mask clears the middle so the form reads on
 * a calm canvas, and fades the drawing out at the edges. Drawn in `currentColor`, so the
 * caller's text class sets the ink and it follows the theme; the pivot takes `--primary`.
 */
export function Wormhole({ className }: { className?: string }) {
  return (
    <div
      aria-hidden
      className={cn("overflow-hidden", className)}
      style={{
        maskImage:
          "radial-gradient(ellipse 60% 70% at center, transparent 18%, black 52%, black 80%, transparent 100%)",
      }}
    >
      <WormholeLandscape className="absolute inset-0 size-full portrait:hidden" />
      <WormholePortrait className="absolute inset-0 size-full landscape:hidden" />
    </div>
  );
}
